        create("q", json!({})),
        create("a.fifo", json!({})),
        create("b", json!({"Fifo": true})),
        create("c", json!({"ContentBasedDeduplication": true})),
        create("d", json!({"DeadLetterQueue": "q"})),
        create("e", json!({"DeadLetterQueue": "nope", "MaxReceiveCount": 2})),
        create("f.fifo", json!({"Fifo": true, "DeadLetterQueue": "q", "MaxReceiveCount": 2})),
    ]);
    assert_eq!(responses[0], ok());
    assert_eq!(responses[1], ok());
    let codes: Vec<_> = responses[2..].iter().map(code).collect();
    assert_eq!(
        codes,
        [
            "QueueAlreadyExists",
            "QueueNameInvalid",
            "QueueNameInvalid",
            "InvalidParameterValue",
            "InvalidParameterValue",
            "QueueDoesNotExist",
            "InvalidParameterValue",
        ]
    );
}

